:root {
  --ink: #202b36;
  --paper: #fffdf7;
  --coral: #ed7058;
  --mist: #dce8e6;
  --line: #bed1ce;
}

.session-pass {
  box-sizing: border-box;
  width: 468px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.pass-top {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--coral);
}

.pass-code {
  margin-left: auto;
  color: var(--coral);
}

.pass-body {
  padding: 16px 18px 14px;
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--coral);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.detail {
  margin: 8px 0 0;
  font-size: 13px;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  background: var(--mist);
}

.time {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  font-size: 12px;
  line-height: 1.2;
}

.time strong {
  font-size: 11px;
  letter-spacing: 0.06em;
}

.enter-button {
  border: 0;
  border-radius: 7px;
  padding: 8px 12px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
